<?php
namespace MarinePortal\Auth;
class Auth0Controller { public function __construct(private array $config){} public function login(): void { $s=bin2hex(random_bytes(16)); $_SESSION['oauth_state']=$s; $q=http_build_query(['response_type'=>'code','client_id'=>$this->config['auth0']['client_id'],'redirect_uri'=>$this->config['app']['url'].'/auth/callback','scope'=>'openid profile email','state'=>$s]); header('Location: https://'.$this->config['auth0']['domain'].'/authorize?'.$q); exit; } public function callback(): void { if(($_GET['state']??'')!==($_SESSION['oauth_state']??'')) { http_response_code(400); echo 'Invalid state'; exit; } $c=new \GuzzleHttp\Client(); $r=$c->post('https://'.$this->config['auth0']['domain'].'/oauth/token',['form_params'=>['grant_type'=>'authorization_code','client_id'=>$this->config['auth0']['client_id'],'client_secret'=>$this->config['auth0']['client_secret'],'code'=>$_GET['code'],'redirect_uri'=>$this->config['app']['url'].'/auth/callback']]); $d=json_decode((string)$r->getBody(),true); $parts=explode('.',$d['id_token']??''); $payload=json_decode(base64_decode($parts[1]??''),true); $_SESSION['user']=['email'=>strtolower(trim($payload['email']??'')),'name'=>$payload['name']??'']; header('Location: /'); exit; } public function logout(): void { session_destroy(); header('Location: https://'.$this->config['auth0']['domain'].'/v2/logout?client_id='.$this->config['auth0']['client_id'].'&returnTo='.urlencode($this->config['app']['url'])); exit; } }
